head.script:
scwin.onpageload = function() {
	//alert("onpageload");
	window.alert_msg = 'onpageload';

};

scwin.inputCal1_onchange = function() {
	//first
    //alert("inputCal1_onchange");
	window.alert_msg = 'inputCal1_onchange';
};

	scwin.checkVal = function() {
		return window.alert_msg == 'onpageload';
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest();
